#include <bits/stdc++.h>
using namespace std;using U=uint32_t;using Row=array<int,5>;using Layer=array<Row,25>;using Stack=array<Layer,4>;using Masks=array<array<U,20>,25>;
int mod(int x){return (x%5+5)%5;}int a[5]={1,0,1,1,1},b[5]={0,1,1,2,3};
int jidx(int i,int j){return j<i?j:j-1;}int tcol(int i){return i==0?1:0;}
int rankbasis(const array<U,20>& rows,U *bas){int r=0;for(U x:rows)while(x){int k=31-__builtin_clz(x);if(bas[k])x^=bas[k];else{bas[k]=x;r++;break;}}return r;}
struct Val{array<uint8_t,20> col;U bits;};
vector<Val> domain(const array<U,20>& rows){U bas[20]={};rankbasis(rows,bas);vector<U> sols{0};for(int f=0;f<20;f++)if(!bas[f]){U x=1u<<f;for(int k=f+1;k<20;k++)if(bas[k]&&(__builtin_popcount(bas[k]&x)&1))x|=1u<<k;int n=sols.size();for(int j=0;j<n;j++)sols.push_back(sols[j]^x);}vector<Val> out;set<array<uint8_t,20>> seen;for(U x:sols){if(x&1)continue;Val v;v.bits=x;bool ok=true;for(int k=0;k<20;k++){U m=rows[k]&x;if(__builtin_popcount(m)!=2){ok=false;break;}U z=0;for(int l=0;l<4;l++)if((m>>(5*l))&31)z|=1u<<l;if(!(z&1))z^=15;v.col[k]=z==3?0:z==5?1:2;}if(ok&&seen.insert(v.col).second)out.push_back(v);}return out;}
Masks masks(const Stack& H){Masks m{};for(int l=0;l<4;l++)for(const Row& r:H[l])for(int i=0;i<5;i++)for(int j=0;j<5;j++)if(i!=j)m[5*i+r[i]][5*jidx(i,j)+r[j]]|=1u<<(5*l+r[tcol(i)]);for(auto &f:m)for(U x:f)assert(__builtin_popcount(x)==4);return m;}
int over4(const Stack& H){int v=0;for(int omitted=0;omitted<5;omitted++){int n[625]={};for(auto &l:H)for(auto &r:l){int k=0;for(int j=0;j<5;j++)if(j!=omitted)k=5*k+r[j];if(++n[k]>2)v++;}}return v;}
bool samecosets(const Stack& H){for(auto &l:H)for(int j=2;j<5;j++){int c=mod(l[0][j]-l[0][0]-(j-1)*l[0][1]);for(auto r:l)if(mod(r[j]-r[0]-(j-1)*r[1])!=c)return false;}return true;}
struct Score{int rigid_dirs,rigid_fibers,collisions,rank_sum;int value()const{return 1000*max(0,rigid_dirs-3)+20*rigid_fibers+50*collisions+rank_sum;}};
Score evaluate(const Stack& H,const Masks& m){int d=0,f=0,rs=0;for(int i=0;i<5;i++){bool rigid=false;for(int u=0;u<5;u++){U bas[20]={};int r=rankbasis(m[5*i+u],bas);assert(r<=17);rs+=r;if(r==17){rigid=true;f++;}}d+=rigid;}return {d,f,over4(H),rs};}
struct CSP{array<vector<Val>,25>d;long long nodes=0,limit;vector<vector<int>> ans;int col(int i,int x,int j){return d[i][x].col[5*jidx(i/5,j/5)+j%5];}
 bool prop(vector<vector<int>>& D,deque<int>& q){bool in[25]={};for(int i:q)in[i]=true;while(!q.empty()){int i=q.front();q.pop_front();in[i]=false;if(D[i].empty())return false;for(int j=0;j<25;j++)if(i/5!=j/5){int c=-1;bool multi=false;for(int v:D[i]){int s=col(i,v,j);if(c<0)c=s;else if(c!=s){multi=true;break;}}if(multi)continue;auto &v=D[j];auto n=v.size();v.erase(remove_if(v.begin(),v.end(),[&](int x){return col(j,x,i)==c;}),v.end());if(v.empty())return false;if(n!=v.size()&&!in[j]){q.push_back(j);in[j]=true;}}}return true;}
 int dfs(vector<vector<int>> D,deque<int> q){if(++nodes>limit)return -1;if(!prop(D,q))return 0;int k=-1;size_t n=SIZE_MAX;for(int i=0;i<25;i++)if(D[i].size()>1&&D[i].size()<n){k=i;n=D[i].size();}if(k<0){ans=move(D);return 1;}for(int x:D[k]){auto Z=D;Z[k]={x};int r=dfs(move(Z),{k});if(r)return r;}return 0;}
 int solve(const Masks& m,long long cap){nodes=0;limit=cap;vector<vector<int>> D(25);deque<int> q;for(int i=0;i<25;i++){d[i]=domain(m[i]);for(int j=0;j<(int)d[i].size();j++)D[i].push_back(j);q.push_back(i);}return dfs(move(D),move(q));}
 vector<Row> witness(const Stack&H){vector<Row> w;for(int l=0;l<4;l++)for(auto r:H[l]){Row t;for(int i=0;i<5;i++){int v=5*i+r[i];t[i]=2*r[i]+((d[v][ans[v][0]].bits>>(5*l+r[tcol(i)]))&1);}w.push_back(t);}assert(w.size()==100);for(int i=0;i<5;i++)for(int j=i+1;j<5;j++){set<pair<int,int>> p;for(auto r:w)p.insert({r[i],r[j]});assert(p.size()==100);}return w;}};
Stack cosets(mt19937_64 &rng){Stack H;for(int l=0;l<4;l++){Row s{0,0,0,0,0};if(l)for(int j=2;j<5;j++)s[j]=rng()%5;for(int x=0;x<5;x++)for(int y=0;y<5;y++)for(int i=0;i<5;i++)H[l][5*x+y][i]=mod(a[i]*x+b[i]*y+s[i]);}return H;}
void mutate(Stack& H,mt19937_64&rng){int l=1+rng()%3,j=rng()%5,x=rng()%5,y=(x+1+rng()%4)%5;if(rng()%10==0){int k=(j+1+rng()%4)%5;for(auto &r:H[l])swap(r[j],r[k]);}else for(auto &r:H[l]){if(r[j]==x)r[j]=y;else if(r[j]==y)r[j]=x;}}
uint64_t stackhash(const Stack&H){array<vector<int>,4> z;for(int l=0;l<4;l++){for(auto r:H[l]){int t=0;for(int x:r)t=t*5+x;z[l].push_back(t);}sort(z[l].begin(),z[l].end());}sort(z.begin(),z.end());uint64_t h=1469598103934665603ULL;for(auto &a:z)for(int x:a){h^=x;h*=1099511628211ULL;}return h;}
int heuristic(int argc,char**argv){int seconds=argc>1?atoi(argv[1]):10;uint64_t seed=argc>2?strtoull(argv[2],0,10):42;mt19937_64 rng(seed);auto start=chrono::steady_clock::now();auto elapsed=[&](){return chrono::duration<double>(chrono::steady_clock::now()-start).count();};long long tested=0,viable=0,closed=0,unknown=0,nodes=0,restarts=0;int best=INT_MAX;unordered_set<uint64_t> seen;Stack H;Score sc{};
while(elapsed()<seconds){if(tested%400==0){
  int bst=INT_MAX;for(int i=0;i<40;i++){auto G=cosets(rng);auto s=evaluate(G,masks(G));if(s.value()<bst){bst=s.value();H=G;sc=s;}}restarts++;
 }Stack G=H;mutate(G,rng);if(rng()%4==0)mutate(G,rng);auto m=masks(G);auto ns=evaluate(G,m);tested++;int delta=ns.value()-sc.value();double T=20.0+30.0*(400-(tested%400))/400.0;if(delta<=0||generate_canonical<double,53>(rng)<exp(-delta/T)){H=G;sc=ns;}if(samecosets(G))continue;best=min(best,ns.value());if(ns.rigid_dirs>3||ns.collisions)continue;auto h=stackhash(G);if(!seen.insert(h).second)continue;viable++;CSP c;int r=c.solve(m,20000);nodes+=c.nodes;if(r==1){auto w=c.witness(G);cout<<"SAT_WITNESS\n";for(auto a:w){for(int x:a)cout<<x<<" ";cout<<"\n";}return 0;}if(r==0)closed++;else {unknown++;cerr<<"UNKNOWN_STACK "<<seed<<" "<<tested<<" ";for(auto &l:G)for(auto &r:l)for(int v:r)cerr<<v;cerr<<"\n";}if(viable%10000==0)cerr<<"tested "<<tested<<" viable "<<viable<<" closed "<<closed<<" unknown "<<unknown<<"\n";
}cout<<"tested "<<tested<<" viable "<<viable<<" closed "<<closed<<" unknown "<<unknown<<" nodes "<<nodes<<" restarts "<<restarts<<" best_score "<<best<<" seed "<<seed<<"\n";return 0;}
using Off=array<int,4>;
Row off(int k){return {0,0,k/25,k/5%5,k%5};}
int oi(Row r){return 25*mod(r[2])+5*mod(r[3])+mod(r[4]);}
Off canon(Off s){Off best=s;for(int t:s)for(int k=1;k<=4;k++){Off r;for(int i=0;i<4;i++){Row v;for(int j=0;j<5;j++)v[j]=k*(off(s[i])[j]-off(t)[j]);r[i]=oi(v);}sort(r.begin(),r.end());best=min(best,r);}return best;}
Stack make(Off s){Stack H;for(int l=0;l<4;l++)for(int x=0;x<5;x++)for(int y=0;y<5;y++)for(int i=0;i<5;i++)H[l][5*x+y][i]=mod(a[i]*x+b[i]*y+off(s[l])[i]);return H;}
bool duplicate4(Off s){int d=-1;for(int k=0;k<3;k++)if(s[k]==s[k+1])d=s[k];if(d<0)return false;for(int t:s)if(t!=d)for(int x=0;x<5;x++)for(int y=0;y<5;y++){int n=0;for(int j=0;j<5;j++)n+=mod(a[j]*x+b[j]*y+off(t)[j]-off(d)[j])==0;if(n>=4)return true;}return false;}
int exact(int argc,char**argv){int shard=argc>2?atoi(argv[2]):0,shards=argc>3?atoi(argv[3]):1;assert(shards>0&&shard>=0&&shard<shards);long long rep=0,total=0,double2=0,dup4=0,ranks=0,csp=0,unk=0,nodes=0;for(int x=0;x<125;x++)for(int y=x;y<125;y++)for(int z=y;z<125;z++){Off s{0,x,y,z};if((x==0&&y==0)||(x==y&&y==z)||s!=canon(s))continue;long long id=rep++;if(id%shards!=shard)continue;total++;if(s[0]==s[1]&&s[2]==s[3]){double2++;continue;}if(duplicate4(s)){dup4++;continue;}Stack H=make(s);auto m=masks(H);auto score=evaluate(H,m);if(score.rigid_dirs>=4){ranks++;continue;}CSP solver;int r=solver.solve(m,1000000);nodes+=solver.nodes;if(r==0)csp++;else if(r==-1){unk++;cerr<<"UNKNOWN_OFFSETS ";for(int t:s)cerr<<t<<" ";cerr<<"\n";}else{auto w=solver.witness(H);cout<<"SAT_WITNESS\n";for(auto q:w){for(int v:q)cout<<v<<" ";cout<<"\n";}return 0;}}cout<<"total_representatives "<<rep<<" shard_cases "<<total<<" repeated_two_pairs "<<double2<<" duplicate_four_agree "<<dup4<<" rank_filter "<<ranks<<" csp_unsat "<<csp<<" unknown "<<unk<<" nodes "<<nodes<<"\n";return 0;}
int main(int argc,char**argv){if(argc>1&&string(argv[1])=="exact")return exact(argc,argv);return heuristic(argc,argv);}
